<script>
const $=id=>document.getElementById(id),preview=$('preview'),ctx=preview.getContext('2d');let image=null;
function roundedRect(c,x,y,w,h,r){r=Math.min(r,w/2,h/2);c.beginPath();c.moveTo(x+r,y);c.arcTo(x+w,y,x+w,y+h,r);c.arcTo(x+w,y+h,x,y+h,r);c.arcTo(x,y+h,x,y,r);c.arcTo(x,y,x+w,y,r);c.closePath()}
function draw(size=512){const source=$('source').value,bg=$('bg').value,fg=$('fg').value,r=+$('radius').value,p=+$('padding').value;ctx.clearRect(0,0,size,size);const s=size/512;ctx.save();ctx.fillStyle=bg;roundedRect(ctx,0,0,size,size,r*s);ctx.clip();if(source==='image'&&image){const iw=image.naturalWidth||image.width,ih=image.naturalHeight||image.height,scale=Math.min((size-2*p*s)/iw,(size-2*p*s)/ih),w=iw*scale,h=ih*scale;ctx.drawImage(image,(size-w)/2,(size-h)/2,w,h)}else{ctx.fillStyle=fg;ctx.textAlign='center';ctx.textBaseline='middle';ctx.font=`${source==='emoji'?'420':'bold 380'}px ${source==='emoji'?'Apple Color Emoji, Segoe UI Emoji, sans-serif':'Arial, sans-serif'}`;ctx.fillText(source==='emoji'?($('emoji').value||'🚀'):(($('text').value||'S').slice(0,3)),size/2,size/2+size*.03)}ctx.restore()}
function updateFields(){const v=$('source').value;$('emojiField').hidden=v!=='emoji';$('textField').hidden=v!=='text';draw()}
$('file').addEventListener('change',e=>{const f=e.target.files?.[0];if(!f)return;const u=URL.createObjectURL(f);const im=new Image();im.onload=()=>{image=im;URL.revokeObjectURL(u);$('source').value='image';updateFields();$('status').textContent='Image loaded. Adjust options and generate.'};im.src=u});$('source').addEventListener('change',updateFields);['emoji','text','bg','fg','radius','padding'].forEach(id=>$(id).addEventListener('input',draw));
function pngData(size){const c=document.createElement('canvas');c.width=c.height=size;const x=c.getContext('2d');x.clearRect(0,0,size,size);const source=$('source').value,bg=$('bg').value,fg=$('fg').value,r=+$('radius').value,p=+$('padding').value; x.save();x.fillStyle=bg;roundedRect(x,0,0,size,size,r*size/512);x.clip();if(source==='image'&&image){const iw=image.naturalWidth||image.width,ih=image.naturalHeight||image.height,scale=Math.min((size-2*p*size/512)/iw,(size-2*p*size/512)/ih),w=iw*scale,h=ih*scale;x.drawImage(image,(size-w)/2,(size-h)/2,w,h)}else{x.fillStyle=fg;x.textAlign='center';x.textBaseline='middle';x.font=`${source==='emoji'?'420':'bold 380'}px ${source==='emoji'?'Apple Color Emoji, Segoe UI Emoji, sans-serif':'Arial, sans-serif'}`;x.fillText(source==='emoji'?($('emoji').value||'🚀'):(($('text').value||'S').slice(0,3)),size/2,size/2+size*.03)}x.restore();return c.toDataURL('image/png')}
function download(data,name){const a=document.createElement('a');a.href=data;a.download=name;document.body.appendChild(a);a.click();a.remove()}
$('generate').onclick=()=>{const sizes=[...document.querySelectorAll('.size:checked')].map(x=>+x.value);if(!sizes.length){$('status').textContent='Select at least one size.';return}if($('source').value==='image'&&!image){$('status').textContent='Please upload an image first.';return}const grid=$('resultGrid');grid.innerHTML='';const lines=[];sizes.forEach(size=>{const data=pngData(size),item=document.createElement('div');item.className='result-item';const c=document.createElement('canvas');c.width=c.height=size;c.style.width='64px';c.style.height='64px';const x=c.getContext('2d'),im=new Image();im.onload=()=>x.drawImage(im,0,0,size,size);im.src=data;item.appendChild(c);const strong=document.createElement('strong');strong.textContent=`${size}×${size}`;item.appendChild(strong);const b=document.createElement('button');b.className='download';b.type='button';b.textContent='DOWNLOAD';b.onclick=()=>download(data,`favicon-${size}x${size}.png`);item.appendChild(b);grid.appendChild(item);if(size===16||size===32||size===180)lines.push(`<link rel="icon" type="image/png" sizes="${size}x${size}" href="/path/to/favicon-${size}x${size}.png">`)}$('snippet').value=lines.join('\n');$('results').hidden=false;$('status').textContent=`Generated ${sizes.length} favicon size${sizes.length===1?'':'s'}.`;};$('copySnippet').onclick=async()=>{try{await navigator.clipboard.writeText($('snippet').value)}catch(e){$('snippet').select();document.execCommand('copy')}$('copySnippet').textContent='COPIED';setTimeout(()=>$('copySnippet').textContent='COPY',900)};$('reset').onclick=()=>{image=null;$('file').value='';$('source').value='image';$('bg').value='#635BFF';$('fg').value='#FFFFFF';$('radius').value=18;$('padding').value=8;$('emoji').value='🚀';$('text').value='S';$('results').hidden=true;$('status').textContent='Upload an image or choose Emoji / Text.';updateFields()};draw();
</script>
